  "watches": [
    {
      "name": "Todo creation and structure",
      "scenarios": [
        "features/todo-creation.feature:New todo is created when Enter is pressed",
        "features/todo-creation.feature:Input is trimmed before creating a todo",
        "features/todo-creation.feature:Empty input after trimming does not create a todo",
        "features/todo-creation.feature:Main and footer are hidden when there are no todos",
        "features/todo-creation.feature:Main and footer are shown when a todo exists"
      ]
    },
    {
      "name": "Todo toggle and completion",
      "scenarios": [
        "features/todo-toggle.feature:Clicking the checkbox marks a todo as completed",
        "features/todo-toggle.feature:Clicking a completed todo's checkbox marks it active",
        "features/todo-toggle.feature:Mark all as complete toggles all todos",
        "features/todo-toggle.feature:Mark all as complete unchecks all when all are already completed",
        "features/todo-toggle.feature:Toggle-all checkbox updates when individual todos are toggled",
        "features/todo-toggle.feature:Clear completed removes only completed todos",
        "features/todo-toggle.feature:Clear completed button is hidden when no todos are completed"
      ]
    },
    {
      "name": "Todo editing and deletion",
      "scenarios": [
        "features/todo-editing.feature:Double-clicking a todo label activates editing mode",
        "features/todo-editing.feature:Editing is saved on blur",
        "features/todo-editing.feature:Editing is saved on Enter",
        "features/todo-editing.feature:Empty edit destroys the todo",
        "features/todo-editing.feature:Escape cancels editing and restores the original title",
        "features/todo-editing.feature:Destroy button removes a todo"
      ]
    },
    {
      "name": "Counter and routing",
      "scenarios": [
        "features/todo-routing.feature:Counter shows the number of active todos",
        "features/todo-routing.feature:Counter uses singular \"item\" for one active todo",
        "features/todo-routing.feature:Routing shows all todos by default",
        "features/todo-routing.feature:Active filter shows only active todos",
        "features/todo-routing.feature:Completed filter shows only completed todos",
        "features/todo-routing.feature:Filter link gets selected class for current route",
        "features/todo-routing.feature:Updating a todo while filtered re-filters it accordingly"
      ]
    },
    {
      "name": "Persistence",
      "scenarios": [
        "features/todo-persistence.feature:Todos are persisted to localStorage",
        "features/todo-persistence.feature:Completed state is persisted",
        "features/todo-persistence.feature:Editing state is not persisted",
        "features/todo-persistence.feature:Todos survive page reload",
        "features/todo-persistence.feature:Active filter is persisted on reload",
        "features/todo-persistence.feature:Stored todo items have id, title, and completed keys"
      ]
    }
  ]
}

